import{_ as r,c as a,o as c,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"搜索缓存：查询缓存、文档缓存与快照","description":"","frontmatter":{"title":"搜索缓存：查询缓存、文档缓存与快照","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#6.3","branch":"main","level":1,"order":6.3},"headers":[],"relativePath":"posts/projects/zfeed/06-search-rpc-service/03-search-caching-query-cache-doc-cache-and-snapshots.md","filePath":"posts/projects/zfeed/06-search-rpc-service/03-search-caching-query-cache-doc-cache-and-snapshots.md","lastUpdated":1779632679000}'),t={name:"posts/projects/zfeed/06-search-rpc-service/03-search-caching-query-cache-doc-cache-and-snapshots.md"};function i(l,e,h,n,p,s){return c(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="搜索缓存-查询缓存、文档缓存与快照" tabindex="-1">搜索缓存：查询缓存、文档缓存与快照 <a class="header-anchor" href="#搜索缓存-查询缓存、文档缓存与快照" aria-label="Permalink to &quot;搜索缓存：查询缓存、文档缓存与快照&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/backend.go" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/backend.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/mysql.go" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/mysql.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env" target="_blank" rel="noreferrer">deploy/.env</a></li></ul></details><p>Search RPC 服务实现了一套多层缓存策略，用于提供稳定分页、降低高频搜索下的数据库负载，并保证热门查询的性能稳定。该系统区分短期查询结果缓存和长期稳定搜索快照。</p><h2 id="两层-redis-缓存架构" tabindex="-1">两层 Redis 缓存架构 <a class="header-anchor" href="#两层-redis-缓存架构" aria-label="Permalink to &quot;两层 Redis 缓存架构&quot;">​</a></h2><p>缓存系统分为两个逻辑层：查询快照缓存（页面级）和文档摘要缓存（实体级）。</p><h3 id="_1-查询快照缓存-页面级" tabindex="-1">1. 查询快照缓存（页面级） <a class="header-anchor" href="#_1-查询快照缓存-页面级" aria-label="Permalink to &quot;1. 查询快照缓存（页面级）&quot;">​</a></h3><p>这一层会缓存特定搜索查询、模式和页码对应的 ID 列表及基础元数据。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L19-L19" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#19</a> 它用于快速返回热门关键词的前几页搜索结果。</p><ul><li>Key 结构：<code>search:cache:q:{version}:{entity}:{mode}:{query_hash}:{page}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L91-L91" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#91</a></li><li>版本控制：使用 <code>searchQueryCacheVersion = 1</code>，方便缓存对象结构迁移。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L22-L22" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#22</a></li><li>TTL 抖动：为防止大量缓存 key 同时过期导致“惊群”，TTL 会在 30 到 90 秒之间抖动。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L25-L28" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#25-28</a></li></ul><h3 id="_2-文档摘要缓存-实体级" tabindex="-1">2. 文档摘要缓存（实体级） <a class="header-anchor" href="#_2-文档摘要缓存-实体级" aria-label="Permalink to &quot;2. 文档摘要缓存（实体级）&quot;">​</a></h3><p>这一层存储单个用户或内容项补全后的数据。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L20-L20" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#20</a> 查询快照缓存保存结果的“顺序”，而文档摘要缓存保存这些结果的“内容”。</p><ul><li>TTL：比查询缓存更长，通常围绕 600 秒进行抖动。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L30-L33" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#30-33</a></li></ul><p>数据实体包括：</p><ul><li><code>searchCachedUserDoc</code>：存储 <code>UserID</code>、<code>Nickname</code>、<code>Avatar</code> 和 <code>Bio</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L53-L61" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#53-61</a></li><li><code>searchCachedContentDoc</code>：存储 <code>ContentID</code>、<code>AuthorName</code>、<code>Title</code>、<code>CoverURL</code> 和分数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L63-L77" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#63-77</a></li></ul><h3 id="缓存控制流" tabindex="-1">缓存控制流 <a class="header-anchor" href="#缓存控制流" aria-label="Permalink to &quot;缓存控制流&quot;">​</a></h3><p>下图展示 <code>SearchContentsLogic</code> 如何通过 <code>queryContentsWithCache</code> 函数与缓存层交互。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L104-L127" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#104-127</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L187-L210" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#187-210</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L345-L364" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#345-364</a></p><h2 id="分布式锁与缓存击穿防护" tabindex="-1">分布式锁与缓存击穿防护 <a class="header-anchor" href="#分布式锁与缓存击穿防护" aria-label="Permalink to &quot;分布式锁与缓存击穿防护&quot;">​</a></h2><p>为了防止同一个搜索查询的多个并发请求同时打到数据库（缓存击穿），系统使用 <code>redislock.NewRedisLock</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L195-L196" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#195-196</a></p><ul><li>锁 key：由查询缓存 key 派生，并追加 <code>:lock</code> 后缀。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L345-L345" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#345</a></li><li>等待机制：如果某个进程未能获取锁，会进入 <code>waitUserQueryCache</code>（或 <code>waitContentQueryCache</code>），短时间轮询 Redis，查看并发进程是否已完成缓存填充。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L205-L207" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#205-207</a></li><li>回退：如果无法获取锁且等待超时，系统会直接回退到数据库查询，以保证可用性。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L208-L209" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#208-209</a></li></ul><h2 id="从缓存模拟-cursor-分页" tabindex="-1">从缓存模拟 cursor 分页 <a class="header-anchor" href="#从缓存模拟-cursor-分页" aria-label="Permalink to &quot;从缓存模拟 cursor 分页&quot;">​</a></h2><p>搜索系统的一个独特能力是从第 0 页缓存中模拟基于 cursor 的分页。如果请求携带 <code>cursor &gt; 0</code>，系统会检查该 cursor 对应的结果是否已经包含在缓存的“第 0 页”中，也就是最常见的搜索入口结果。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L67-L73" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#67-73</a></p><ul><li>逻辑：<code>cachedContentsAfterCursor</code> 加载第一页缓存。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L168-L170" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#168-170</a></li><li>偏移计算：查找 cursor 在缓存列表中的索引。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L178-L178" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#178</a></li><li>子切片：如果找到 cursor 且后续剩余条目足够，则返回从该 cursor 之后开始的缓存结果切片。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go#L183-L184" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go#183-184</a></li></ul><h2 id="用于稳定分页的搜索快照" tabindex="-1">用于稳定分页的搜索快照 <a class="header-anchor" href="#用于稳定分页的搜索快照" aria-label="Permalink to &quot;用于稳定分页的搜索快照&quot;">​</a></h2><p>标准缓存用于提升性能，而快照用于保证一致性。当 <code>SearchSnapshotEnabled</code> 为 true 时，<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L14-L14" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#14</a> 系统会为用户的搜索会话捕获一组固定结果。</p><h3 id="快照生命周期" tabindex="-1">快照生命周期 <a class="header-anchor" href="#快照生命周期" aria-label="Permalink to &quot;快照生命周期&quot;">​</a></h3><ol><li>创建：在第一页（offset 0）时，系统向后端查询一大批结果（最多 <code>SEARCH_SNAPSHOT_MAX_ITEMS</code>，默认 100）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L224-L233" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#224-233</a></li><li>持久化：该批结果会以“Snapshot” 形式保存到 Redis，并拥有唯一 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L101-L105" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#101-105</a></li><li>消费：后续请求提供 <code>PageToken</code>，其中包含 <code>SnapshotID</code> 和当前 <code>Offset</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L166-L166" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#166</a></li><li>过期：快照生命周期很短（默认 60 秒），避免占用过多内存。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L30-L30" target="_blank" rel="noreferrer">deploy/.env#30</a></li></ol><h3 id="快照实现映射" tabindex="-1">快照实现映射 <a class="header-anchor" href="#快照实现映射" aria-label="Permalink to &quot;快照实现映射&quot;">​</a></h3><p>下图将逻辑快照概念连接到内部代码结构。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L159-L165" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#159-165</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L25-L33" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#25-33</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L101-L110" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#101-110</a></p><h2 id="配置参数" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数" aria-label="Permalink to &quot;配置参数&quot;">​</a></h2><p>缓存行为由环境变量和 <code>Config</code> 结构体控制。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L8-L22" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#8-22</a></p><table tabindex="0"><thead><tr><th>变量</th><th>配置字段</th><th>说明</th></tr></thead><tbody><tr><td><code>SEARCH_CACHE_ENABLED</code></td><td><code>SearchCacheEnabled</code></td><td>查询/文档缓存的总开关。</td></tr><tr><td><code>SEARCH_SNAPSHOT_ENABLED</code></td><td><code>SearchSnapshotEnabled</code></td><td>稳定快照分页开关。</td></tr><tr><td><code>SEARCH_QUERY_CACHE_TTL_SECONDS</code></td><td><code>SearchQueryCacheTTLSeconds</code></td><td>查询页面结果的基础 TTL。</td></tr><tr><td><code>SEARCH_DOC_CACHE_TTL_SECONDS</code></td><td><code>SearchDocCacheTTLSeconds</code></td><td>实体摘要的基础 TTL。</td></tr><tr><td><code>SEARCH_QUERY_CACHE_MAX_PAGES</code></td><td><code>SearchQueryCacheMaxPages</code></td><td>最大缓存页深度，通常为 3-5。</td></tr><tr><td><code>SEARCH_SNAPSHOT_MAX_ITEMS</code></td><td><code>SearchSnapshotMaxItems</code></td><td>单个快照捕获的最大结果数。</td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L26-L34" target="_blank" rel="noreferrer">deploy/.env#26-34</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L13-L21" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#13-21</a></p>',33)])])}const d=r(t,[["render",i]]);export{b as __pageData,d as default};
